  ('wolf', 44, 'Team spirit is your thing. Bring it to a solo task.', 'Cheer yourself on.', 'Drag through it.'),
  ('wolf', 45, 'Today, the strongest wolf is the one who asks for help.', 'Ask for support.', 'Pretend you''re fine.'),
  ('wolf', 46, 'You defend your opinions fiercely. Hear a different one today.', 'Listen openly.', 'Argue back.'),
  ('wolf', 47, 'Your pack is your home. Make your home a nice place tonight.', 'Tidy and relax.', 'Stay out late.'),
  ('wolf', 48, 'Today, change isn''t a threat. It''s a new trail.', 'Explore the new path.', 'Resist it.'),
  ('wolf', 49, 'You''re steady in storms. Be steady in small things too.', 'Handle details calmly.', 'Stress about little stuff.'),
  ('wolf', 50, 'Loyalty includes honesty. Tell a friend the truth kindly.', 'Be honest kindly.', 'Stay quiet to keep peace.'),
  ('wolf', 51, 'Today, make a new friend without vetting them for a month.', 'Be open fast.', 'Run a background check.'),
  ('wolf', 52, 'Your pack loves you for you. No need to perform strength.', 'Be real.', 'Act tough.'),
  ('wolf', 53, 'Today, guard your peace like you guard your people.', 'Protect your calm.', 'Join every fight.'),
  ('wolf', 54, 'You lead well in groups. Today, follow well too.', 'Follow someone''s lead.', 'Take over.'),
  ('wolf', 55, 'Being strong-willed means finishing what you start. Finish one thing.', 'Complete a task.', 'Start a new one.'),
  ('wolf', 56, 'Today, your loyalty is noticed. Let it be enough.', 'Trust it''s seen.', 'Demand recognition.'),
  ('wolf', 57, 'The pack thrives on shared meals and stories. Plan one.', 'Plan a group dinner.', 'Eat alone at your desk.'),
  ('wolf', 58, 'You protect others well. Protect a little time for your dreams.', 'Work on your dream.', 'Only work for others.'),
  ('wolf', 59, 'Today, let someone outside your circle surprise you.', 'Stay curious.', 'Stay guarded.'),
  ('wolf', 60, 'You''re the heart of your pack. Hearts need rest too.', 'Slow down tonight.', 'Keep going.')
) as v (animal, day_index, message, do_text, dont_text)
join public.animal_auras a on lower(btrim(a.name)) = v.animal
on conflict (aura_id, season, day_index) do nothing;

-- Every animal must be found, or the seed silently skips its rows.
do $$
declare
  v_missing text;
begin
  select string_agg(v.animal, ', ') into v_missing
  from unnest(array['bear', 'cat', 'deer', 'dolphin', 'eagle', 'elephant', 'fox', 'lion', 'otter', 'owl', 'parrot', 'peacock', 'snake', 'unicorn', 'wolf']) as v (animal)
  where not exists (select 1 from public.animal_auras a where lower(btrim(a.name)) = v.animal);
  if v_missing is not null then
    raise exception 'daily aura seed: animals not found in animal_auras: %', v_missing;
  end if;
end $$;

commit;
